+	drm_bridge_put(dp->next_bridge);
+
 unregister_aux:
 	drm_dp_aux_unregister(&dp->aux);
 
@@ -2014,6 +2033,7 @@ void dw_dp_unbind(struct dw_dp *dp)
 {
 	disable_irq(dp->irq);
